#[ignore]
fn separate_loops() {
    let input = &[(1, 2), (2, 3), (3, 1), (1, 1), (2, 2), (3, 3)];
    let output = dominoes::chain(input);
    assert!(output.is_some());
    assert_correct(input, output.unwrap());
}

